SELECT json_build_object(
 'server_version', current_setting('server_version_num'),
 'routine_grants',COALESCE((SELECT json_agg(json_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a WHERE n.nspname=ANY(__SCHEMAS__) AND p.prokind IN ('f','p')),'[]'::json),
 'database', current_database(),
 'schema_names',COALESCE((SELECT json_agg(nspname ORDER BY nspname) FROM pg_namespace WHERE nspname=ANY(__SCHEMAS__)),'[]'::json),
 'tables', COALESCE((SELECT json_agg(x ORDER BY x.schema,x.name) FROM (
   SELECT n.nspname AS schema,c.relname AS name,c.relkind,c.relrowsecurity AS rls,c.relforcerowsecurity AS force_rls,
   (SELECT json_agg(json_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum)
     FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped) AS columns,
   (SELECT json_agg(json_build_object('name',k.conname,'definition',pg_get_constraintdef(k.oid)) ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid=c.oid) AS constraints,
   (SELECT json_agg(indexdef ORDER BY indexname) FROM pg_indexes WHERE schemaname=n.nspname AND tablename=c.relname) AS indexes
   FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=ANY(__SCHEMAS__) AND c.relkind IN ('r','p','f')
 ) x),'[]'::json),
 'views',COALESCE((SELECT json_agg(json_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'options',c.reloptions,'definition',pg_get_viewdef(c.oid,true)) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=ANY(__SCHEMAS__) AND c.relkind IN ('v','m')),'[]'::json),
 'functions',COALESCE((SELECT json_agg(json_build_object('schema',n.nspname,'name',p.proname,'definition',pg_get_functiondef(p.oid),'security_definer',p.prosecdef,'definer_owner',CASE WHEN p.prosecdef THEN pg_get_userbyid(p.proowner) END,'settings',p.proconfig) ORDER BY n.nspname,p.proname,p.oid::regprocedure::text) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=ANY(__SCHEMAS__) AND p.prokind IN ('f','p') AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e')),'[]'::json),
 'policies',COALESCE((SELECT json_agg(json_build_object('schema',schemaname,'table',tablename,'name',policyname,'roles',roles,'command',cmd,'using',qual,'check',with_check) ORDER BY schemaname,tablename,policyname) FROM pg_policies WHERE schemaname=ANY(__SCHEMAS__)),'[]'::json),
 'triggers',COALESCE((SELECT json_agg(pg_get_triggerdef(t.oid) ORDER BY n.nspname,c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=ANY(__SCHEMAS__) AND NOT t.tgisinternal),'[]'::json),
 'types',COALESCE((SELECT json_agg(json_build_object('schema',n.nspname,'name',t.typname,'kind',t.typtype,'base_type',format_type(t.typbasetype,t.typtypmod),'not_null',t.typnotnull,'default',t.typdefault,'enum_labels',(SELECT json_agg(enumlabel ORDER BY enumsortorder) FROM pg_enum WHERE enumtypid=t.oid),'constraints',(SELECT json_agg(pg_get_constraintdef(oid) ORDER BY conname) FROM pg_constraint WHERE contypid=t.oid),'attributes',(SELECT json_agg(json_build_object('name',attname,'type',format_type(atttypid,atttypmod)) ORDER BY attnum) FROM pg_attribute WHERE attrelid=t.typrelid AND attnum>0 AND NOT attisdropped)) ORDER BY n.nspname,t.typname) FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace LEFT JOIN pg_class c ON c.oid=t.typrelid WHERE n.nspname=ANY(__SCHEMAS__) AND (t.typtype IN ('e','d') OR (t.typtype='c' AND c.relkind='c'))),'[]'::json),
 'rules',COALESCE((SELECT json_agg(json_build_object('schema',schemaname,'table',tablename,'name',rulename,'definition',definition) ORDER BY schemaname,tablename,rulename) FROM pg_rules WHERE schemaname=ANY(__SCHEMAS__)),'[]'::json),
 'extensions',COALESCE((SELECT json_agg(json_build_object('name',e.extname,'version',e.extversion,'schema',n.nspname) ORDER BY e.extname) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace),'[]'::json),
 'sequences',COALESCE((SELECT json_agg(json_build_object('schema',schemaname,'name',sequencename,'start',start_value,'increment',increment_by,'min',min_value,'max',max_value,'cycle',cycle,'cache',cache_size) ORDER BY schemaname,sequencename) FROM pg_sequences WHERE schemaname=ANY(__SCHEMAS__)),'[]'::json),
 'foreign_keys',COALESCE((SELECT json_agg(json_build_object('schema',n.nspname,'table',c.relname,'target_schema',rn.nspname,'target_table',rc.relname,'definition',pg_get_constraintdef(k.oid)) ORDER BY n.nspname,c.relname,k.conname) FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_class rc ON rc.oid=k.confrelid JOIN pg_namespace rn ON rn.oid=rc.relnamespace WHERE k.contype='f' AND n.nspname=ANY(__SCHEMAS__)),'[]'::json),
 'publications',COALESCE((SELECT json_agg(pubname ORDER BY pubname) FROM pg_publication),'[]'::json),
 'foreign_servers',COALESCE((SELECT json_agg(srvname ORDER BY srvname) FROM pg_foreign_server),'[]'::json),
 'grants',COALESCE((SELECT json_agg(json_build_object('schema',table_schema,'table',table_name,'grantee',grantee,'privilege',privilege_type) ORDER BY table_schema,table_name,grantee,privilege_type) FROM information_schema.table_privileges WHERE table_schema=ANY(__SCHEMAS__)),'[]'::json)
);
